import React, { useState } from 'react';
import { Input, Select, DatePicker, Card, Button } from 'antd';
import { SearchOutlined } from '@ant-design/icons';
import { airports } from '../FlightSearch/data/airports';
import dayjs from 'dayjs';
import { useHybridPathInput } from '../../hooks/useHybridPathInput';
import '../../styles/NormalRouteSearch.css';

const { RangePicker } = DatePicker;

const NormalRouteSearch = ({ onSearch }) => {
  const {
    path,
    showAirportSelect,
    currentInput,
    selectedAirport,
    inputRef,
    airportOptions,
    handleInputChange,
    handleAirportSelect,
    handleKeyDown,
    setPath
  } = useHybridPathInput();

  const [excludedSources, setExcludedSources] = useState([]);
  const [apiKey, setApiKey] = useState('');
  const [dateRange, setDateRange] = useState(null);
  const [error, setError] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  // Convert airports data to select options for excluded sources
  const airportOptionsForExcluded = airports.map(airport => ({
    value: airport.IATA,
    label: `${airport.IATA} - ${airport.Name} (${airport.Country})`
  }));

  // Handle search submission
  const handleSearch = () => {
    if (!path) {
      setError('Please enter a path');
      return;
    }

    if (!apiKey) {
      setError('Please enter an API key');
      return;
    }

    if (!dateRange) {
      setError('Please select a date range');
      return;
    }

    setIsSearching(true);
    setError('');

    // Parse the path into segments
    const segments = path.split('-').map(segment => {
      const airports = segment.split('/');
      return {
        airports: airports.map(code => code.trim()),
        isOptional: airports.length > 1
      };
    });

    onSearch({
      path: segments,
      excludedSources,
      apiKey,
      dateRange: {
        start: dateRange[0].format('YYYY-MM-DD'),
        end: dateRange[1].format('YYYY-MM-DD')
      }
    });
  };

  return (
    <Card className="normal-route-search">
      <div className="space-y-4">
        {/* Path Input */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Path
          </label>
          <div className="relative">
            <Input
              ref={inputRef}
              value={path}
              onChange={handleInputChange}
              onKeyDown={handleKeyDown}
              placeholder="Enter path (e.g., NRT/HND-OAK/SFO-JFK/EWR)"
              className="w-full"
              status={error && !path ? 'error' : ''}
            />
            {showAirportSelect && (
              <div className="airport-dropdown">
                {airportOptions.map(option => (
                  <div
                    key={option.value}
                    className="airport-option"
                    onClick={() => handleAirportSelect(option.value, option)}
                  >
                    <span className="airport-code">{option.value}</span>
                    <span className="airport-name">{option.label}</span>
                  </div>
                ))}
                {airportOptions.length === 0 && (
                  <div className="px-4 py-2 text-gray-500 text-sm">
                    No airports found
                  </div>
                )}
              </div>
            )}
            {error && !path && (
              <div className="text-red-500 text-sm mt-1">{error}</div>
            )}
          </div>
        </div>

        {/* Excluded Sources */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Sources Excluded
          </label>
          <Select
            mode="multiple"
            value={excludedSources}
            onChange={setExcludedSources}
            options={airportOptionsForExcluded}
            placeholder="Select airports to exclude"
            className="w-full"
            showSearch
            filterOption={(input, option) =>
              (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
            }
            optionRender={(option) => (
              <div className="airport-option">
                <span className="airport-code">{option.value}</span>
                <span className="airport-name">{option.label}</span>
              </div>
            )}
          />
        </div>

        {/* API Key */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            API Key
          </label>
          <Input.Password
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            placeholder="Enter your API key"
            className="w-full"
            status={error && !apiKey ? 'error' : ''}
          />
          {error && !apiKey && (
            <div className="text-red-500 text-sm mt-1">{error}</div>
          )}
        </div>

        {/* Date Range */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Date Range
          </label>
          <RangePicker
            value={dateRange}
            onChange={setDateRange}
            className="w-full"
            status={error && !dateRange ? 'error' : ''}
          />
          {error && !dateRange && (
            <div className="text-red-500 text-sm mt-1">{error}</div>
          )}
        </div>

        {/* Search Button */}
        <Button
          type="primary"
          icon={<SearchOutlined />}
          onClick={handleSearch}
          loading={isSearching}
          className="w-full"
        >
          Search
        </Button>
      </div>
    </Card>
  );
};

export default NormalRouteSearch;
